node 内部对模块输出 module.exports 的实现变量 module 是 Node 在加载 js 文件前准备的一个变量，并将其传入加载函数
// 准备module对象var module = &#123;  id: &#x27;hello&#x27;,  exports: &#123;&#125;&#125;var load = function (module) &#123;  // 读取的hello.js代码  function greet(name) &#123;    console.log(&#x27;Hello, &#x27; + name + &#x27;!&#x27;)  &#125;  module.exports = greet  // hello.js代码结束  return module.exports&#125;var exported = load(module)// 保存modulesave(module, exported)

默认情况下，Node 准备的 exports 变量和 module.exports 变量实际上是同一个变量，所以一下两种写法都支持
// method 1module.exports = &#123;    foo: foo,    bar: bar&#125;;ormodule.exports.foo = foo;module.exports.bar = bar;// method 2exports.foo = foo;exports.bar = bar;

