有了规范后，我们需要通过工具去约束：commitlint。它要做的就是在我们每次提交 git commit 的时候，都会帮我们检查 commit message 是否符合一定的规范，如果不符合，就让这次提交失败。
具体配置：
# 安装 commitlint cli 和 conventional confignpm install --save-dev @commitlint/&#123;config-conventional,cli&#125;# Windows:npm install --save-dev @commitlint/config-conventional @commitlint/cli# 配置要使用的 commitlint 规则echo &quot;module.exports = &#123;extends: [&#x27;@commitlint/config-conventional&#x27;]&#125;&quot; &gt; commitlint.config.js# 加入到husky中：npx husky add .husky/commit-msg &#x27;npx --no -- commitlint --edit &quot;$1&quot;&#x27;oryarn husky add .husky/commit-msg &#x27;yarn commitlint --edit $1

Javascript 代码风格使用有意义的变量名称变量的名称应该是可描述，有意义的， JavaScript 变量都应该采用驼峰式大小写 ( camelCase) 命名。
// bad ❌const foo = &#x27;JDoe@example.com&#x27;const bar = &#x27;John&#x27;const age = 23const qux = true// good ✅const email = &#x27;John@example.com&#x27;const firstName = &#x27;John&#x27;const age = 23const isActive = true

布尔变量通常需要回答特定问题，例如：
isActivedidSubscribehasLinkedAccount

避免添加不必要的上下文当对象或类已经包含了上下文的命名时，不要再向变量名称添加冗余的上下文。
// bad ❌const user = &#123;  userId: &#x27;296e2589-7b33-400a-b762-007b730c8e6d&#x27;,  userEmail: &#x27;JDoe@example.com&#x27;,  userFirstName: &#x27;John&#x27;,  userLastName: &#x27;Doe&#x27;,  userAge: 23&#125;user.userId//good ✅const user = &#123;  id: &#x27;296e2589-7b33-400a-b762-007b730c8e6d&#x27;,  email: &#x27;JDoe@example.com&#x27;,  firstName: &#x27;John&#x27;,  lastName: &#x27;Doe&#x27;,  age: 23&#125;user.id

避免硬编码值// bad ❌setTimeout(clearSessionData, 900000)//good ✅const SESSION_DURATION_MS = 15 * 60 * 1000setTimeout(clearSessionData, SESSION_DURATION_MS)

使用有意义的函数名称函数名称需要描述函数的实际作用，即使很长也没关系。函数名称通常使用动词，但返回布尔值的函数可能是个例外 — 它可以采用 是或否 问题的形式，函数名也应该是驼峰式的。
// bad ❌function toggle() &#123;  // ...&#125;function agreed(user) &#123;  // ...&#125;//good ✅function toggleThemeSwitcher() &#123;  // ...&#125;function didAgreeToAllTerms(user) &#123;  // ...&#125;

限制参数的数量尽管这条规则可能有争议，但函数最好是有 3 个以下参数。如果参数较多可能是以下两种情况之一：

该函数做的事情太多，应该拆分。
传递给函数的数据以某种方式相关，可以作为专用数据结构传递。

// bad ❌function sendPushNotification(title, message, image, isSilent, delayMs) &#123;  // ...&#125;sendPushNotification(&#x27;New Message&#x27;, &#x27;...&#x27;, &#x27;http://...&#x27;, false, 1000)//good ✅function sendPushNotification(&#123; title, message, image, isSilent, delayMs &#125;) &#123;  // ...&#125;const notificationConfig = &#123;  title: &#x27;New Message&#x27;,  message: &#x27;...&#x27;,  image: &#x27;http://...&#x27;,  isSilent: false,  delayMs: 1000&#125;sendPushNotification(notificationConfig)

避免在一个函数中做太多事情一个函数应该一次做一件事，这有助于减少函数的大小和复杂性，使测试、调试和重构更容易。
// bad ❌function pingUsers(users) &#123;  users.forEach((user) =&gt; &#123;    const userRecord = database.lookup(user)    if (!userRecord.isActive()) &#123;      ping(user)    &#125;  &#125;)&#125;//good ✅function pingInactiveUsers(users) &#123;  users.filter(!isUserActive).forEach(ping)&#125;function isUserActive(user) &#123;  const userRecord = database.lookup(user)  return userRecord.isActive()&#125;

避免使用布尔标志作为参数函数含有布尔标志的参数意味这个函数是可以被简化的。
// bad ❌function createFile(name, isPublic) &#123;  if (isPublic) &#123;    fs.create(`./public/$&#123;name&#125;`)  &#125; else &#123;    fs.create(name)  &#125;&#125;//good ✅function createFile(name) &#123;  fs.create(name)&#125;function createPublicFile(name) &#123;  createFile(`./public/$&#123;name&#125;`)&#125;

避免写重复的代码如果你写了重复的代码，每次有逻辑改变，你都需要改动多个位置。
// bad ❌function renderCarsList(cars) &#123;  cars.forEach((car) =&gt; &#123;    const price = car.getPrice()    const make = car.getMake()    const brand = car.getBrand()    const nbOfDoors = car.getNbOfDoors()    render(&#123; price, make, brand, nbOfDoors &#125;)  &#125;)&#125;function renderMotorcyclesList(motorcycles) &#123;  motorcycles.forEach((motorcycle) =&gt; &#123;    const price = motorcycle.getPrice()    const make = motorcycle.getMake()    const brand = motorcycle.getBrand()    const seatHeight = motorcycle.getSeatHeight()    render(&#123; price, make, brand, nbOfDoors &#125;)  &#125;)&#125;//good ✅function renderVehiclesList(vehicles) &#123;  vehicles.forEach((vehicle) =&gt; &#123;    const price = vehicle.getPrice()    const make = vehicle.getMake()    const brand = vehicle.getBrand()    const data = &#123; price, make, brand &#125;    switch (vehicle.type) &#123;      case &#x27;car&#x27;:        data.nbOfDoors = vehicle.getNbOfDoors()        break      case &#x27;motorcycle&#x27;:        data.seatHeight = vehicle.getSeatHeight()        break    &#125;    render(data)  &#125;)&#125;

避免副作用在 JavaScript 中，你应该更喜欢函数式模式而不是命令式模式。换句话说，大多数情况下我们都应该保持函数纯洁。副作用可能会修改共享状态和资源，从而导致一些奇怪的问题。所有的副作用都应该集中管理，例如你需要更改全局变量或修改文件，可以专门写一个 util 来做这件事。
// bad ❌let date = &#x27;21-8-2021&#x27;function splitIntoDayMonthYear() &#123;  date = date.split(&#x27;-&#x27;)&#125;splitIntoDayMonthYear()// Another function could be expecting date as a stringconsole.log(date) // [&#x27;21&#x27;, &#x27;8&#x27;, &#x27;2021&#x27;];//good ✅function splitIntoDayMonthYear(date) &#123;  return date.split(&#x27;-&#x27;)&#125;const date = &#x27;21-8-2021&#x27;const newDate = splitIntoDayMonthYear(date)// Original vlaue is intactconsole.log(date) // &#x27;21-8-2021&#x27;;console.log(newDate) // [&#x27;21&#x27;, &#x27;8&#x27;, &#x27;2021&#x27;];

另外，如果你将一个可变值传递给函数，你应该直接克隆一个新值返回，而不是直接改变该它。
// bad ❌function enrollStudentInCourse(course, student) &#123;  course.push(&#123; student, enrollmentDate: Date.now() &#125;)&#125;//good ✅function enrollStudentInCourse(course, student) &#123;  return [...course, &#123; student, enrollmentDate: Date.now() &#125;]&#125;

使用非负条件// bad ❌function isUserNotVerified(user) &#123;  // ...&#125;if (!isUserNotVerified(user)) &#123;  // ...&#125;//good ✅function isUserVerified(user) &#123;  // ...&#125;if (isUserVerified(user)) &#123;  // ...&#125;

尽可能使用简写// bad ❌if (isActive === true) &#123;  // ...&#125;if (firstName !== &#x27;&#x27; &amp;&amp; firstName !== null &amp;&amp; firstName !== undefined) &#123;  // ...&#125;const isUserEligible = user.isVerified() &amp;&amp; user.didSubscribe() ? true : false//good ✅if (isActive) &#123;  // ...&#125;if (!!firstName) &#123;  // ...&#125;const isUserEligible = user.isVerified() &amp;&amp; user.didSubscribe()

避免过多分支尽早 return 会使你的代码线性化、更具可读性且不那么复杂。
// bad ❌function addUserService(db, user) &#123;  if (!db) &#123;    if (!db.isConnected()) &#123;      if (!user) &#123;        return db.insert(&#x27;users&#x27;, user)      &#125; else &#123;        throw new Error(&#x27;No user&#x27;)      &#125;    &#125; else &#123;      throw new Error(&#x27;No database connection&#x27;)    &#125;  &#125; else &#123;    throw new Error(&#x27;No database&#x27;)  &#125;&#125;//good ✅function addUserService(db, user) &#123;  if (!db) throw new Error(&#x27;No database&#x27;)  if (!db.isConnected()) throw new Error(&#x27;No database connection&#x27;)  if (!user) throw new Error(&#x27;No user&#x27;)  return db.insert(&#x27;users&#x27;, user)&#125;

优先使用 map 而不是 switch 语句既能减少复杂度又能提升性能。
// bad ❌const getColorByStatus = (status) =&gt; &#123;  switch (status) &#123;    case &#x27;success&#x27;:      return &#x27;green&#x27;    case &#x27;failure&#x27;:      return &#x27;red&#x27;    case &#x27;warning&#x27;:      return &#x27;yellow&#x27;    case &#x27;loading&#x27;:    default:      return &#x27;blue&#x27;  &#125;&#125;//good ✅const statusColors = &#123;  success: &#x27;green&#x27;,  failure: &#x27;red&#x27;,  warning: &#x27;yellow&#x27;,  loading: &#x27;blue&#x27;&#125;const getColorByStatus = (status) =&gt; statusColors[status] || &#x27;blue&#x27;

使用可选链接const user = &#123;  email: &#x27;JDoe@example.com&#x27;,  billing: &#123;    iban: &#x27;...&#x27;,    swift: &#x27;...&#x27;,    address: &#123;      street: &#x27;Some Street Name&#x27;,      state: &#x27;CA&#x27;    &#125;  &#125;&#125;// bad ❌const email = (user &amp;&amp; user.email) || &#x27;N/A&#x27;const street = (user &amp;&amp; user.billing &amp;&amp; user.billing.address &amp;&amp; user.billing.address.street) || &#x27;N/A&#x27;const state = (user &amp;&amp; user.billing &amp;&amp; user.billing.address &amp;&amp; user.billing.address.state) || &#x27;N/A&#x27;//good ✅const email = user?.email ?? &#x27;N/A&#x27;const street = user?.billing?.address?.street ?? &#x27;N/A&#x27;const street = user?.billing?.address?.state ?? &#x27;N/A&#x27;

避免回调回调很混乱，会导致代码嵌套过深，使用 Promise 替代回调。
// bad ❌getUser(function (err, user) &#123;  getProfile(user, function (err, profile) &#123;    getAccount(profile, function (err, account) &#123;      getReports(account, function (err, reports) &#123;        sendStatistics(reports, function (err) &#123;          console.error(err)        &#125;)      &#125;)    &#125;)  &#125;)&#125;)//good ✅getUser()  .then(getProfile)  .then(getAccount)  .then(getReports)  .then(sendStatistics)  .catch((err) =&gt; console.error(err))// or using Async/Await ✅✅async function sendUserStatistics() &#123;  try &#123;    const user = await getUser()    const profile = await getProfile(user)    const account = await getAccount(profile)    const reports = await getReports(account)    return sendStatistics(reports)  &#125; catch (e) &#123;    console.error(err)  &#125;&#125;

处理抛出的错误和 reject 的 promise// bad ❌try &#123;  // Possible erronous code&#125; catch (e) &#123;  console.log(e)&#125;//good ✅try &#123;  // Possible erronous code&#125; catch (e) &#123;  // Follow the most applicable (or all):  // 1- More suitable than console.log  console.error(e)  // 2- Notify user if applicable  alertUserOfError(e)  // 3- Report to server  reportErrorToServer(e)  // 4- Use a custom error handler  throw new CustomError(e)&#125;

只注释业务逻辑// bad ❌function generateHash(str) &#123;  // Hash variable  let hash = 0  // Get the length of the string  let length = str.length  // If the string is empty return  if (!length) &#123;    return hash  &#125;  // Loop through every character in the string  for (let i = 0; i &lt; length; i++) &#123;    // Get character code.    const char = str.charCodeAt(i)    // Make the hash    hash = (hash &lt;&lt; 5) - hash + char    // Convert to 32-bit integer    hash &amp;= hash  &#125;&#125;// good ✅function generateHash(str) &#123;  let hash = 0  let length = str.length  if (!length) &#123;    return hash  &#125;  for (let i = 0; i &lt; length; i++) &#123;    const char = str.charCodeAt(i)    hash = (hash &lt;&lt; 5) - hash + char    hash = hash &amp; hash // Convert to 32bit integer  &#125;  return hash&#125;

ES6 优化原生 JS（ES5） 代码风格使用默认参数// bad ❌function printAllFilesInDirectory(dir) &#123;  const directory = dir || &#x27;./&#x27;  //   ...&#125;// good ✅function printAllFilesInDirectory(dir = &#x27;./&#x27;) &#123;  // ...&#125;

对象结构取值const obj = &#123;  a: 1,  b: 2,  c: 3,  d: 4,  e: 5&#125;// bad ❌const f = obj.a + obj.dconst g = obj.c + obj.e// good ✅const &#123; a, b, c, d, e &#125; = objconst f = a + dconst g = c + e

ES6 的解构赋值虽然好用。但是要注意解构的对象不能为 undefined、null。否则会报错，故要给被解构的对象一个默认值。
const &#123; a, b, c, d, e &#125; = obj || &#123;&#125;

拓展运算符合并数据合并数组或者对象，用 ES5 的写法有些冗余
const a = [1, 2, 3]const b = [1, 5, 6]const obj1 = &#123;  a: 1&#125;const obj2 = &#123;  b: 1&#125;// bad ❌const c = a.concat(b) //[1,2,3,1,5,6]const obj = Object.assign(&#123;&#125;, obj1, obj2) // &#123;a:1, b:1&#125;// good ✅const c = [...new Set([...a, ...b])] //[1,2,3,5,6]const obj = &#123; ...obj1, ...obj2 &#125; // &#123;a:1, b:1&#125;

拼接字符const name = &#x27;小明&#x27;const score = 59// bad ❌let result = &#x27;&#x27;if (score &gt; 60) &#123;  result = `$&#123;name&#125;的考试成绩及格`&#125; else &#123;  result = `$&#123;name&#125;的考试成绩不及格`&#125;// good ✅const result = `$&#123;name&#125;$&#123;score &gt; 60 ? &#x27;的考试成绩及格&#x27; : &#x27;的考试成绩不及格&#x27;&#125;`

includes 替代多条件判断// bad ❌f(    type == 1 ||    type == 2 ||    type == 3 ||    type == 4 ||)&#123;   //...&#125;// good ✅const condition = [1,2,3,4];if( condition.includes(type) )&#123;   //...&#125;

列表查找某一项const a = [1, 2, 3, 4, 5]// bad ❌const result = a.filter((item) =&gt; &#123;  return item === 3&#125;)// good ✅const result = a.find((item) =&gt; &#123;  return item === 3&#125;)

数组扁平化// bad ❌const deps = &#123;  采购部: [1, 2, 3],  人事部: [5, 8, 12],  行政部: [5, 14, 79],  运输部: [3, 64, 105]&#125;let member = []for (let item in deps) &#123;  const value = deps[item]  if (Array.isArray(value)) &#123;    member = [...member, ...value]  &#125;&#125;member = [...new Set(member)]// good ✅const member = Object.values(deps).flat(Infinity)

可选链操作符获取对象属性值// bad ❌const name = obj &amp;&amp; obj.name// good ✅const name = obj?.name

动态对象属性名// bad ❌let obj = &#123;&#125;let index = 1let key = `topic$&#123;index&#125;`obj[key] = &#x27;话题内容&#x27;// good ✅obj[`topic$&#123;index&#125;`] = &#x27;话题内容&#x27;

判断非空// bad ❌if (value !== null &amp;&amp; value !== undefined &amp;&amp; value !== &#x27;&#x27;) &#123;  //...&#125;// good ✅if ((value ?? &#x27;&#x27;) !== &#x27;&#x27;) &#123;  //...&#125;

Vue 组件风格Vue 单文件组件风格指南内容节选自 Vue 官方风格指南。
组件数据组件的 data 必须是一个函数。
// bad ❌export default &#123;  data: &#123;    foo: &#x27;bar&#x27;  &#125;&#125;;// good ✅export default &#123;  data() &#123;    return &#123;      foo: &#x27;bar&#x27;    &#125;;  &#125;&#125;;

单文件组件文件名称单文件组件的文件名应该要么始终是单词大写开头 (PascalCase)，要么始终是横线连接 (kebab-case)。
// bad ❌mycomponent.vuemyComponent.vue// good ✅my - component.vueMyComponent.vue

紧密耦合的组件名和父组件紧密耦合的子组件应该以父组件名作为前缀命名。
// bad ❌components/|- TodoList.vue|- TodoItem.vue└─ TodoButton.vue// good ✅components/|- TodoList.vue|- TodoListItem.vue└─ TodoListItemButton.vue

自闭合组件在单文件组件中没有内容的组件应该是自闭合的。
&lt;!-- bad --&gt;&lt;my-component&gt;&lt;/my-component&gt;&lt;!-- good --&gt;&lt;my-component /&gt;

Prop 名大小写在声明 prop 的时候，其命名应该始终使用 camelCase，而在模板中应该始终使用 kebab-case。
// bad ❌export default &#123;  props: &#123;    &#x27;greeting-text&#x27;: String  &#125;&#125;;// good ✅export default &#123;  props: &#123;    greetingText: String  &#125;&#125;;

&lt;!-- bad --&gt;&lt;welcome-message greetingText=&quot;hi&quot; /&gt;&lt;!-- good --&gt;&lt;welcome-message greeting-text=&quot;hi&quot; /&gt;

指令缩写指令缩写，用 : 表示 v-bind: ，用 @ 表示 v-on:
&lt;!-- bad --&gt;&lt;input v-bind:value=&quot;value&quot; v-on:input=&quot;onInput&quot; /&gt;&lt;!-- good --&gt;&lt;input :value=&quot;value&quot; @input=&quot;onInput&quot; /&gt;

Props 顺序标签的 Props 应该有统一的顺序，依次为指令、属性和事件。
&lt;my-component  v-if=&quot;if&quot;  v-show=&quot;show&quot;  v-model=&quot;value&quot;  ref=&quot;ref&quot;  :key=&quot;key&quot;  :text=&quot;text&quot;  @input=&quot;onInput&quot;  @change=&quot;onChange&quot;/&gt;

组件选项的顺序组件选项应该有统一的顺序。
export default &#123;  name: &#x27;&#x27;,  components: &#123;&#125;,  props: &#123;&#125;,  emits: [],  setup() &#123;&#125;,  data() &#123;&#125;,  computed: &#123;&#125;,  watch: &#123;&#125;,  created() &#123;&#125;,  mounted() &#123;&#125;,  unmounted() &#123;&#125;,  methods: &#123;&#125;&#125;

组件选项中的空行组件选项较多时，建议在属性之间添加空行。
export default &#123;  computed: &#123;    formattedValue() &#123;      // ...    &#125;,    styles() &#123;      // ...    &#125;  &#125;,  methods: &#123;    onInput() &#123;      // ...    &#125;,    onChange() &#123;      // ...    &#125;  &#125;&#125;

单文件组件顶级标签的顺序单文件组件应该总是让顶级标签的顺序保持一致，且标签之间留有空行。
&lt;template&gt; ... &lt;/template&gt;&lt;script&gt;  /* ... */&lt;/script&gt;&lt;style&gt;  /* ... */&lt;/style&gt;

