2、双向数据绑定原理vue实现对数据的双向绑定，通过对数据劫持结合发布者-订阅者模式实现的。
2.1 Object.definePropertyvue通过Object.defineProperty来实现数据劫持，会对数据对象每个属性添加对应的get和set方法，对数据进行读取和赋值操作就分别调用get和set方法。
Object.defineProperty(data, key, &#123;    enumerable: true,    configurable: true,    get: function() &#123;        // do something        return val;    &#125;,    set: function(newVal) &#123;        // do something    &#125;&#125;);

我们可以将一些方法放到里面，从而完成对数据的监听（劫持）和视图的同步更新。

2.2 过程说明实现双向数据绑定，首先要对数据进行数据监听，需要一个监听器Observer，监听所有属性。如果属性发生变化，会调用setter和getter，再去告诉订阅者Watcher是否需要更新。由于订阅者有很多个，我们需要一个消息订阅器Dep来专门收集这些订阅者，然后在监听器Observer和订阅者Watcher之间进行统一管理。还有，我们需要一个指令解析器Complie，对每个元素进行扫描和解析，将相关指令对应初始化成一个订阅者Watcher，并替换模板数据或绑定相应函数。当订阅者Watcher接收到相应属性的变化，就会执行对应的更新函数，从而更新视图。

3、实现ObserverObserver是一个数据监听器，核心方法是我们提到过的Object.defineProperty。如果要监听所有属性的话，则需要通过递归遍历，对每个子属性都defineProperty。
/** * 监听器构造函数 * @param &#123;Object&#125; data 被监听数据 */function Observer(data) &#123;    if (!data || typeof data !== &quot;object&quot;) &#123;        return;    &#125;    this.data = data;    this.walk(data);&#125;Observer.prototype = &#123;    /**     * 属性遍历     */    walk: function(data) &#123;        var self = this;        Object.keys(data).forEach(function(key) &#123;            self.defineReactive(data, key, data[key]);        &#125;);    &#125;,    /**     * 监听函数     */    defineReactive: function(data, key, val) &#123;        observe(val);        Object.defineProperty(data, key, &#123;            enumerable: true,            configurable: true,            get: function() &#123;                return val;            &#125;,            set: function(newVal) &#123;                if (newVal === val) &#123;                    return;                &#125;                val = newVal;                console.log(&quot;属性：&quot; + key + &quot;被监听了，现在值为：&quot; + newVal);                updateView(newVal);            &#125;        &#125;);        updateView(val);    &#125;&#125;/** * 监听器 * @param &#123;Object&#125; data 被监听对象 */function observe(data) &#123;    return new Observer(data);&#125;/** * vue构造函数 * @param &#123;Object&#125; options 所有入参 */function MyVue(options) &#123;    this.vm = this;    this.data = options.data;    // 监听数据    observe(this.data);    return this;&#125;/** * 更新视图 * @param &#123;*&#125; val */function updateView(val) &#123;    var $name = document.querySelector(&quot;#name&quot;);    $name.innerHTML = val;&#125;var myvm = new MyVue(&#123;    el: &quot;#demo&quot;,    data: &#123;        name: &quot;hello word&quot;    &#125;&#125;);


4、实现Dep在流程介绍中，我们需要创建一个可以订阅者的订阅器Dep，主要负责手机订阅者，属性变化的时候执行相应的订阅者，更新函数。下面稍加改造Observer，就可以插入我们的订阅器。
Observer.prototype = &#123;    // ...    /**     * 监听函数     */    defineReactive: function(data, key, val) &#123;        var dep = new Dep();        observe(val);        Object.defineProperty(data, key, &#123;            enumerable: true,            configurable: true,            get: function() &#123;                // 判断是否需要添加订阅者 什么时候添加订阅者呢？ 与实际页面DOM有关联的data属性才添加相应的订阅者                if (Dep.target) &#123;                    // 添加一个订阅者                    dep.addSub(Dep.target);                &#125;                return val;            &#125;,            set: function(newVal) &#123;                if (newVal === val) &#123;                    return;                &#125;                val = newVal;                console.log(&quot;属性：&quot; + key + &quot;被监听了，现在值为：&quot; + newVal);                // 通知所有订阅者                dep.notify(newVal);            &#125;        &#125;);        updateView(val);        // 订阅器标识本身实例        Dep.target = dep;        // 强行执行getter，往订阅器中添加订阅者        var v = data[key];        // 释放自己        Dep.target = null;    &#125;&#125;/** * 监听器 * @param &#123;Object&#125; data 被监听对象 */function observe(data) &#123;    return new Observer(data);&#125;/** * 订阅器 */function Dep() &#123;    this.subs = [];    this.target = null;&#125;Dep.prototype = &#123;    addSub: function(sub) &#123;        this.subs.push(sub);        console.log(&quot;this.subs:&quot;, this.subs);    &#125;,    notify: function(data) &#123;        this.subs.forEach(function(sub) &#123;            sub.update(data);        &#125;);    &#125;,    update: function(val) &#123;        updateView(val)    &#125;&#125;;// ...

PS:将订阅器Dep添加到一个订阅者设计到getter里面，是为了让Watcher初始化进行触发。
5、实现Watcher订阅者Watcher在初始化的时候需要将自己添加到订阅器Dep中，那该如何添加呢？我们已经知道监听器Observer是在get函数执行添加了订阅者Watcher的操作，所以我们只要在订阅者Watcher初始化的时候触发对应的get函数去执行添加订阅者操作。那么，怎样去触发get函数？很简单，只需获取对应的属性值就可以触发了，因为我们已经用Object.defineProperty监听了所有属性。vue在这里做了个技巧处理，就是咋我们添加订阅者的时候，做一个判断，判断是否是事先缓存好的Dep.target，在订阅者添加成功后，把target重置null即可。
// .../** * 订阅者 * @param &#123;Object&#125; vm vue对象 * @param &#123;String&#125; exp 属性值 * @param &#123;Function&#125; cb 回调函数 */function Watcher(vm, exp, cb) &#123;    this.vm = vm;    this.exp = exp;    this.cb = cb;    // 将自己添加到订阅器    this.value = this.get();&#125;Watcher.prototype = &#123;    update: function() &#123;        this.run();    &#125;,    run: function() &#123;        var value = this.vm.data[this.exp];        var oldVal = this.value;        if (value !== oldVal) &#123;            this.value = value;            this.cb.call(this.vm, value, oldVal);        &#125;    &#125;,    get: function() &#123;        // 缓存自己 做个标记        Dep.target = this;        // 强制执行监听器里的get函数        // this.vm.data[this.exp] 调用getter，添加一个订阅者sub，存入到全局变量subs        var value = this.vm.data[this.exp];        // 释放自己        Dep.target = null;        return value;    &#125;&#125;;/** * vue构造函数 * @param &#123;Object&#125; options 所有入参 */function MyVue(options) &#123;    this.vm = this;    this.data = options.data;    observe(this.data);    var $name = document.querySelector(&quot;#name&quot;);    // 给name属性添加一个订阅者到订阅器中，当属性发生变化后，触发回调    var w = new Watcher(this, &quot;name&quot;, function(val) &#123;        $name.innerHTML = val;    &#125;);    return this;&#125;

到这里，其实已经实现了我们的双向数据绑定：能够根据初始数据初始化页面特定元素，同时当数据改变也能更新视图。
5、实现Compile步骤4整个过程都能有去解析DOM节点，而是直接固定节点进行替换。接下来我们就来实现一个解析器，完成一些解析和绑定工作。

获取页面的DOM节点，遍历存入到文档碎片对象中；
解析出文本节点，匹配&#123;&#123;&#125;&#125;（暂时只做”&#123;&#123;&#125;&#125;”的解析），用初始化数据替换，并添加相应订阅者；
分离出节点的指令v-on、v-bind和v-model，绑定相应的事件和函数；


// .../** * 编译器构造函数 * @param &#123;String&#125; el 根元素 * @param &#123;Object&#125; vm vue对象 */function Compile(el, vm) &#123;    this.vm = vm;    this.el = document.querySelector(el);    this.fragment = null;    this.init();&#125;Compile.prototype = &#123;    /**     * 初始     */    init: function() &#123;        if (this.el) &#123;            console.log(&quot;this.el:&quot;, this.el);            // 移除页面元素生成文档碎片            this.fragment = this.nodeToFragment(this.el);            // 编译文档碎片            this.compileElement(this.fragment);            this.el.appendChild(this.fragment);        &#125; else &#123;            console.log(&quot;DOM Selector is not exist&quot;);        &#125;    &#125;,    /**     * 页面DOM节点转化成文档碎片     */    nodeToFragment: function(el) &#123;        var fragment = document.createDocumentFragment();        var child = el.firstChild;        // 此处添加打印，出来的不是页面中原始的DOM，而是编译后的？        // NodeList是引用关系，在编译后相应的值被替换了，这里打印出来的NodeList是后来被引用更新了的        console.log(&quot;el:&quot;, el);        // console.log(&quot;el.firstChild:&quot;, el.firstChild.nodeValue);        while (child) &#123;            // append后，原el上的子节点被删除了，挂载在文档碎片上            fragment.appendChild(child);            child = el.firstChild;        &#125;        return fragment;    &#125;,    /**     * 编译文档碎片，遍历到当前是文本节点则去编译文本节点，如果当前是元素节点，并且存在子节点，则继续递归遍历     */    compileElement: function(fragment) &#123;        var childNodes = fragment.childNodes;        var self = this;        [].slice.call(childNodes).forEach(function(node) &#123;            // var reg = /\&#123;\&#123;\s*(.+)\s*\&#125;\&#125;/g;            var reg = /\&#123;\&#123;\s*((?:.|\n)+?)\s*\&#125;\&#125;/g;            var text = node.textContent;            if (self.isElementNode(node)) &#123;                self.compileAttr(node);            &#125; else if (self.isTextNode(node) &amp;&amp; reg.test(text)) &#123;                reg.lastIndex = 0                /* var match;                while(match = reg.exec(text)) &#123;                    self.compileText(node, match[1]);                &#125; */                self.compileText(node, reg.exec(text)[1]);            &#125;            if (node.childNodes &amp;&amp; node.childNodes.length) &#123;                self.compileElement(node);            &#125;        &#125;);    &#125;,    /**     * 编译属性     */    compileAttr: function(node) &#123;        var nodeAttrs = node.attributes;        var self = this;        Array.prototype.forEach.call(nodeAttrs, function(attr) &#123;            var attrName = attr.name;            // 只对vue本身指令进行操作            if (self.isDirective(attrName)) &#123;                var exp = attr.value;                // v-on指令                if (self.isOnDirective(attrName)) &#123;                    self.compileOn(node, self.vm, exp, attrName);                &#125;                // v-bind指令                if(self.isBindDirective(attrName)) &#123;                    self.compileBind(node, self.vm, exp, attrName);                &#125;                // v-model                else if (self.isModelDirective(attrName)) &#123;                    self.compileModel(node, self.vm, exp, attrName);                &#125;                node.removeAttribute(attrName);            &#125;        &#125;)    &#125;,    /**     * 编译文档碎片节点文本，即对标记替换     */    compileText: function(node, exp) &#123;        var self = this;        var exps = exp.split(&quot;.&quot;);        var initText = this.vm.data[exp];        // 初始化视图        this.updateText(node, initText);        // 添加一个订阅者到订阅器        var w = new Watcher(this.vm, exp, function(val) &#123;            self.updateText(node, val);        &#125;);    &#125;,    /**     * 编译v-on指令     */    compileOn: function(node, vm, exp, attrName) &#123;        // @xxx v-on:xxx        var onRE = /^@|^v-on:/;        var eventType = attrName.replace(onRE, &quot;&quot;);        var cb = vm.methods[exp];        if (eventType &amp;&amp; cb) &#123;            node.addEventListener(eventType, cb.bind(vm), false);        &#125;    &#125;,    /**     * 编译v-bind指令     */    compileBind: function (node, vm, exp, attrName) &#123;        // :xxx v-bind:xxx        var bindRE = /^:|^v-bind:/;        var attr = attrName.replace(bindRE, &quot;&quot;);        var val = vm.data[exp];        node.setAttribute(attr, val);    &#125;,    /**     * 编译v-model指令     */    compileModel: function(node, vm, exp, attrName) &#123;        var self = this;        var val = this.vm.data[exp];        // 初始化视图        this.modelUpdater(node, val);        // 添加一个订阅者到订阅器        new Watcher(this.vm, exp, function(value) &#123;            self.modelUpdater(node, value);        &#125;);        // 绑定input事件        node.addEventListener(&quot;input&quot;, function(e) &#123;            var newVal = e.target.value;            if (val === newVal) &#123;                return;            &#125;            self.vm.data[exp] = newVal;            // val = newVal;        &#125;);    &#125;,    /**     * 更新文档碎片相应的文本节点     */    updateText: function(node, val) &#123;        node.textContent = typeof val === &quot;undefined&quot; ? &quot;&quot; : val;    &#125;,    /**     * model更新节点     */    modelUpdater: function(node, val, oldVal) &#123;        node.value = typeof val == &quot;undefined&quot; ? &quot;&quot; : val;    &#125;,    /**     * 属性是否是vue指令，包括v-xxx:,:xxx,@xxx     */    isDirective: function(attrName) &#123;        var dirRE = /^v-|^@|^:/;        return dirRE.test(attrName);    &#125;,    /**     * 属性是否是v-on指令     */    isOnDirective: function(attrName) &#123;        var onRE = /^v-on:|^@/;        return onRE.test(attrName);    &#125;,    /**     * 属性是否是v-bind指令     */    isBindDirective: function (attrName) &#123;        var bindRE = /^v-bind:|^:/;        return bindRE.test(attrName);    &#125;,    /**     * 属性是否是v-model指令     */    isModelDirective: function(attrName) &#123;        var mdRE = /^v-model/;        return mdRE.test(attrName);    &#125;,    /**     * 判断元素节点     */    isElementNode: function(