5、其他5.1 proxy代理data可能注意到了，我们不管是在赋值还是取值，都是在myvm.data.someAttr上操作的，而在vue上我们习惯直接myvm.someAttr这种形式。怎样实现呢？同样，我们可以用Object.defineProperty对data所有属性做一个代理，即访问vue实例属性时，代理到data上。很简单，实现如下：
/** * 将数据拓展到vue的根，方便读取和设置 */MyVue.prototype.proxy = function(key) &#123;    var self = this;    Object.defineProperty(this, key, &#123;        enumerable: true,        configurable: true,        get: function proxyGetter() &#123;            return self.data[key];        &#125;,        set: function proxySetter(newVal) &#123;            self.data[key] = newVal;        &#125;    &#125;);&#125;


5.2 parsePath上面对于data的操作只是到对于简单的基本类型属性，对于对象属性的改变该怎么更新到位呢？其实，只要深度遍历对象属性路径，就可以找到要访问属性值。
/** * 根据对象属性路径，最终获取值 * @param &#123;Object&#125; obj 对象 * @param &#123;String&#125; path 路径 * return 值 */function parsePath(obj, path) &#123;    var bailRE = /[^\w.$]/;    if (bailRE.test(path)) &#123;        return    &#125;    var segments = path.split(&#x27;.&#x27;);    for (var i = 0; i &lt; segments.length; i++) &#123;        if (!obj) &#123; return &#125;        obj = obj[segments[i]];    &#125;    return obj;&#125;

用这个方法替换我们的所有取值操作vm[exp] =&gt; parsePath(vm, exp)

6、新增属性的双向数据绑定6.1 给对象添加属性Vue 不允许在已经创建的实例上动态添加新的根级响应式属性 (root-level reactive property)。然而它可以使用 Vue.set(object, key, value) 方法将响应属性添加到嵌套的对象上。也就是我们需要在Vue原型上添加一个set方法去设置新添加的属性，新属性同样要进行监听和添加订阅者。
/** * vue的set方法，用于外部新增属性 Vue.$set(target, key, val) * @param &#123;Object&#125; target 数据 * @param &#123;String&#125; key 属性 * @param &#123;*&#125; val 值 */function set(target, key, val) &#123;    if (Array.isArray(target)) &#123;        target.length = Math.max(target.length, key);        target.splice(key, 1, val);        return val;    &#125;    if (target.hasOwnProperty(key)) &#123;        target[key] = val;        return val    &#125;    var ob = (target).$Observer;    if (!ob) &#123;        target[key] = val;        return val    &#125;    // 对新增属性定义监听    ob.defineReactive(target, key, val);    ob.dep.notify();    return val;&#125;MyVue.prototype.$set = set;

6.1 给数组对象添加属性把数组看成一个特殊的对象，就很容易理解了，对于unshift、push和splice变异方法是添加了对象的属性的，需要对新加的属性进行监听和添加订阅者。
var arrKeys = [&quot;push&quot;, &quot;pop&quot;, &quot;shift&quot;, &quot;unshift&quot;, &quot;splice&quot;, &quot;sort&quot;, &quot;reverse&quot;];var extendArr = [];arrKeys.forEach(function(key) &#123;    def(extendArr, key, function() &#123;        var result,            arrProto = Array.prototype,            ob = this.$Observer,            arr = arrProto.slice.call(arguments),            inserted,            index;        switch (key) &#123;            case &quot;push&quot;:                inserted = arr;                index = this.length;                break;            case &quot;unshift&quot;:                inserted = arr;                index = 0;                break;            case &quot;splice&quot;:                inserted = arr.slice(2);                index = arr[0];                break;        &#125;        result = arrProto[key].apply(this, arguments);        // 监听新增数组对象属性        if (inserted) &#123;            ob.observeArray(inserted);        &#125;        ob.dep.notify();        return result;    &#125;);&#125;);var arrayKeys = Object.getOwnPropertyNames(extendArr);/** * 监听器构造函数 * @param &#123;Object&#125; data 被监听数据 */function Observer(data) &#123;    this.dep = new Dep();    if (!data || typeof data !== &quot;object&quot;) &#123;        return;    &#125;    // 在每个object上添加一个observer    def(data, &quot;$Observer&quot;, this);    // 继承变异方法    if (Array.isArray(data)) &#123;        // 把数组变异方法的处理，添加到原型链上        data.__proto__ = extendArr;        // 监听数组对象属性        this.observeArray(data);    &#125; else &#123;        this.data = data;        this.walk(data);    &#125;&#125;Observer.prototype = &#123;    // ...    /**     * 监听数组     */    observeArray: function(items) &#123;        console.log(&quot;items:&quot;, items);        for (var i = 0, l = items.length; i &lt; l; i++) &#123;            observe(items[i]);        &#125;    &#125;&#125;;

参数为正数的情况slice()和substring()的第二个参数指定的是字符串最后一个字符后面的位置，而substr()的第二个擦输指定的则是返回的字符串个数。
var stringValue = &quot;hello world&quot;;console.log(stringValue.slice(3)); // &quot;lo world&quot;console.log(stringValue.substring(3)); // &quot;lo world&quot;console.log(stringValue.substr(3)); // &quot;lo world&quot;console.log(stringValue.slice(3, 7)); // &quot;lo w&quot;console.log(stringValue.substring(3, 7)); // &quot;lo w&quot;console.log(stringValue.substr(3, 7)); // &quot;lo worl&quot;
参数有负数的情况slice()方法会将传入的负数与字符串的长度相加，substr()方法将负的第一个参数加上字符串的长度，而将负的第二个参数转化为0。最后，substring()方法会把所有负值参数都转化为0。


var stringValue = &quot;hello world&quot;;console.log(stringValue.slice( -3 )); // &quot;rld&quot;console.log(stringValue.substring( -3 )); // &quot;hellow world&quot;console.log(stringValue.substr( -3 )); // &quot;rld&quot;console.log(stringValue.slice( 3, -4 )); // &quot;lo w&quot;console.log(stringValue.substring( 3, -4 )); // &quot;hel&quot;console.log(stringValue.substr( 3, -4 )); // &quot;&quot;

谈到布局，首先就要想到定位，当别人问我，css的position定位有哪些取值，分别表示什么意思？呃…..

定位position有六个属性值：static、relative、absolute、fixed、sticky和inherit。

static（默认）：元素框正常生成。块级元素生成一个矩形框，作为文档流的一部分；行内元素则会创建一个或多个行框，置于父级元素中。
relative：元素框相对于之前正常文档流中的位置发生偏移，并且原先的位置仍然被占据。发生偏移的时候，可能会覆盖其他元素。
absolute：元素框不再占有文档位置，并且相对于包含块进行偏移（所谓包含块就是最近一级外层元素position不为static的元素）。
fixed：元素框不再占有文档流位置，并且相对于视窗进行定位。
sticky：css3新增属性值，粘性定位，相当于relative和fixed的混合。最初会被当作是relative，相对原来位置进行偏移；一旦超过一定的阈值，会被当成fixed定位，相对于视口定位。

三列布局三列布局，其中一列宽度自适应，在PC端最常用之一，搞定了三列布局，其他一样的套路。
方式一：浮动布局缺点：html结构不正确,当包含区域宽度小于左右框之和，右边框会被挤下来
&lt;style&gt;    .tree-columns-layout.float .left &#123;        float: left;        width: 300px;        background-color: #a00;    &#125;    .tree-columns-layout.float .right &#123;        float: right;        width: 300px;        background-color: #0aa;    &#125;    .tree-columns-layout.float .center &#123;        /* left: 300px;        right: 300px; */        margin: 0 300px;        background-color: #aa0;        overflow: auto;    &#125;&lt;/style&gt;&lt;section class=&quot;tree-columns-layout float&quot;&gt;    &lt;article class=&quot;left&quot;&gt;        &lt;h1&gt;我是浮动布局左框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;right&quot;&gt;        &lt;h1&gt;我是浮动布局右框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;center&quot;&gt;        &lt;h1&gt;我是浮动布局中间框&lt;/h1&gt;    &lt;/article&gt;&lt;/section&gt;

方式二：定位布局缺点：要求父级要有非static定位，如果没有，左右框容易偏移出去
&lt;style&gt;    .tree-columns-layout.position &#123;        position: relative;    &#125;    .tree-columns-layout.position .left &#123;        position: absolute;        left: 0;        top: 0;        width: 300px;        background-color: #a00;    &#125;    .tree-columns-layout.position .right &#123;        position: absolute;        right: 0;        top: 0;        width: 300px;        background-color: #0aa;    &#125;    .tree-columns-layout.position .center &#123;        margin: 0 300px;        background-color: #aa0;        overflow: auto;    &#125;&lt;/style&gt;&lt;section class=&quot;tree-columns-layout position&quot;&gt;    &lt;article class=&quot;left&quot;&gt;        &lt;h1&gt;我是浮动定位左框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;center&quot;&gt;        &lt;h1&gt;我是浮动定位中间框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;right&quot;&gt;        &lt;h1&gt;我是浮动定位右框&lt;/h1&gt;    &lt;/article&gt;&lt;/section&gt;

方式三：表格布局缺点：没什么缺点，恐惧table
&lt;style&gt;    .tree-columns-layout.table &#123;        display: table;        width: 100%;    &#125;    .tree-columns-layout.table &gt; article &#123;        display: table-cell;    &#125;    .tree-columns-layout.table .left &#123;        width: 300px;        background-color: #a00;    &#125;    .tree-columns-layout.table .center &#123;        background-color: #aa0;    &#125;    .tree-columns-layout.table .right &#123;        width: 300px;        background-color: #0aa;    &#125;&lt;/style&gt;&lt;section class=&quot;tree-columns-layout table&quot;&gt;    &lt;article class=&quot;left&quot;&gt;        &lt;h1&gt;我是表格布局左框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;center&quot;&gt;        &lt;h1&gt;我是表格布局中间框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;right&quot;&gt;        &lt;h1&gt;我是表格布局右框&lt;/h1&gt;    &lt;/article&gt;&lt;/section&gt;

方式四：flex弹性布局缺点：兼容性
&lt;style&gt;    .tree-columns-layout.flex &#123;        display: flex;    &#125;    .tree-columns-layout.flex .left &#123;        width: 300px;        flex-shrink: 0; /* 不缩小 */        background-color: #a00;    &#125;    .tree-columns-layout.flex .center &#123;        flex-grow: 1; /* 增大 */        background-color: #aa0;    &#125;    .tree-columns-layout.flex .right &#123;        flex-shrink: 0; /* 不缩小 */        width: 300px;        background-color: #0aa;    &#125;&lt;/style&gt;&lt;section class=&quot;tree-columns-layout flex&quot;&gt;    &lt;article class=&quot;left&quot;&gt;        &lt;h1&gt;我是flex弹性布局左框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;center&quot;&gt;        &lt;h1&gt;我是flex弹性布局中间框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;right&quot;&gt;        &lt;h1&gt;我是flex弹性布局右框&lt;/h1&gt;    &lt;/article&gt;&lt;/section&gt;

方式五：grid栅格布局缺点：兼容性 Firefox 52, Safari 10.1, Chrome 57, Opera 44
&lt;style&gt;    .tree-columns-layout.grid &#123;        display: grid;        grid-template-columns: 300px 1fr 300px;    &#125;    .tree-columns-layout.grid .left &#123;        background-color: #a00;    &#125;    .tree-columns-layout.grid .center &#123;        background-color: #aa0;    &#125;    .tree-columns-layout.grid .right &#123;        background-color: #0aa;    &#125;&lt;/style&gt;&lt;section class=&quot;tree-columns-layout grid&quot;&gt;    &lt;article class=&quot;left&quot;&gt;        &lt;h1&gt;我是grid栅格布局左框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;center&quot;&gt;        &lt;h1&gt;我是grid栅格布局中间框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;right&quot;&gt;        &lt;h1&gt;我是grid栅格布局右框&lt;/h1&gt;    &lt;/article&gt;&lt;/section&gt;

方式六：圣杯布局缺点：需要多加一层标签，html顺序不对，占用了布局框的margin属性
&lt;style&gt;    .tree-columns-layout.cup:after &#123;        clear: both;        content: &quot;&quot;;        display: table;    &#125;    .tree-columns-layout.cup .center &#123;        width: 100%;        float: left;    &#125;    .tree-columns-layout.cup .center &gt; div &#123;        margin: 0 300px;        overflow: auto;        background-color: #aa0;    &#125;    .tree-columns-layout.cup .left &#123;        width: 300px;        float: left;        margin-left: -100%;        background-color: #a00;    &#125;    .tree-columns-layout.cup .right &#123;        width: 300px;        float: left;        margin-left: -300px;        background-color: #0aa;    &#125;&lt;/style&gt;&lt;section class=&quot;tree-columns-layout cup&quot;&gt;    &lt;article class=&quot;center&quot;&gt;        &lt;div&gt;            &lt;h1&gt;我是圣杯布局中间框&lt;/h1&gt;        &lt;/div&gt;    &lt;/article&gt;    &lt;article class=&quot;left&quot;&gt;        &lt;h1&gt;我是圣杯布局左框&lt;/h1&gt;    &lt;/article&gt;    &lt;article class=&quot;right&quot;&gt;        &lt;h1&gt;我是圣杯布局右框&lt;/h1&gt;    &lt;/article&gt;&lt;/section&gt;
